"""Generate the dependency-free site. Run from any directory with Python 3."""
from pathlib import Path
from html import escape
import json
import re
import hashlib

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://lukebrennan.github.io/Maeve-Arden-Photography/'
LOGO_VERSION = hashlib.sha256(b''.join((ROOT/'assets/icons'/name).read_bytes() for name in ('maeve-arden-logo.svg','maeve-arden-wordmark.svg'))).hexdigest()[:8]
FAVICON_VERSION = hashlib.sha256((ROOT/'assets/icons/favicon.svg').read_bytes()).hexdigest()[:8]

# Keep the maintained CSS readable and the served stylesheet compact.
css_source = (ROOT / 'src/style.css').read_text()
css = re.sub(r'/\*.*?\*/', '', css_source, flags=re.S)
css = re.sub(r'\s+', ' ', css)
css = re.sub(r'\s*([{};])\s*', r'\1', css).strip()
(ROOT / 'assets/css/style.css').write_text(css+'\n')
CSS_VERSION = hashlib.sha256(css.encode()).hexdigest()[:8]
JS_VERSION = hashlib.sha256((ROOT/'assets/js/main.js').read_bytes()).hexdigest()[:8]
IMAGE_MANIFEST = json.loads((ROOT/'assets/images/manifest.json').read_text())
PHOTOS = {key:(info['alt'], info['photographer'], info['photoId'])
          for key,info in IMAGE_MANIFEST.items() if 'photoId' in info}

def picture(key, prefix='', sizes='100vw', eager=False, cls='', decorative=False):
    alt = '' if decorative else PHOTOS[key.replace('-landscape', '')][0]
    dims = IMAGE_MANIFEST.get(key, {})
    # The aspect ratio of the box is controlled by CSS; these describe the file.
    width = dims.get('width', dims.get('original_width', 1600))
    height = dims.get('height', dims.get('original_height', 2000))
    widths = (480, 800, 1200, 1600)
    path = f'{prefix}assets/images/{key}'
    avif = ', '.join(f'{path}-{w}.avif {w}w' for w in widths)
    webp = ', '.join(f'{path}-{w}.webp {w}w' for w in widths)
    priority = 'fetchpriority="high" loading="eager"' if eager else 'loading="lazy"'
    return f'<picture class="{cls}" data-photo="{key}"><source type="image/avif" srcset="{avif}" sizes="{sizes}"><img src="{path}-800.webp" srcset="{webp}" sizes="{sizes}" width="{width}" height="{height}" alt="{alt}" {priority} decoding="async"></picture>'

def arrow():
    return '<svg width="18" height="18" viewBox="0 0 20 20" aria-hidden="true"><path d="M3 10h14m-6-6 6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.4"/></svg>'

def previous_arrow():
    return '<svg width="18" height="18" viewBox="0 0 20 20" aria-hidden="true"><path d="M17 10H3m6-6-6 6 6 6" fill="none" stroke="currentColor" stroke-width="1.4"/></svg>'

def expand_icon():
    return '<svg width="17" height="17" viewBox="0 0 18 18" aria-hidden="true"><path d="M4 14 14 4M4 4h10v10" fill="none" stroke="currentColor" stroke-width="1.4"/></svg>'


def brand(prefix=''):
    return f'<a class="brand" href="{prefix}index.html" aria-label="Maeve Arden Photography home"><picture class="brand-picture"><source media="(max-width: 360px)" srcset="{prefix}assets/icons/maeve-arden-wordmark.svg?v={LOGO_VERSION}"><img class="brand-logo" src="{prefix}assets/icons/maeve-arden-logo.svg?v={LOGO_VERSION}" width="450" height="96" alt="" fetchpriority="high" decoding="async"></picture></a>'

def nav(prefix, active, mobile=False):
    links = [('portfolio', 'Selected work'), ('weddings', 'The experience'), ('about', 'About'), ('journal', 'Journal')]
    return ''.join(f'<a href="{prefix}{slug}.html"'+(' aria-current="page"' if slug == active else '')+f'>{label}</a>' for slug, label in links)

def header(prefix, active):
    return f'''<a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><noscript><style>.desktop-nav{{display:flex;flex-wrap:wrap}}.menu-toggle{{display:none}}.header-inner{{flex-wrap:wrap;padding-block:16px}}</style></noscript><div class="header-inner">{brand(prefix)}<nav class="desktop-nav" aria-label="Main navigation">{nav(prefix, active)}<a class="button button-small" href="{prefix}contact.html">Check your date {arrow()}</a></nav><button class="menu-toggle" type="button" aria-label="Open navigation" aria-haspopup="dialog" aria-controls="navigation-dialog" aria-expanded="false" data-menu-open><span>Menu</span><svg width="20" height="16" viewBox="0 0 20 16" aria-hidden="true"><path d="M1 4h18M1 12h18" stroke="currentColor" stroke-width="1.5"/></svg></button></div></header>
<dialog id="navigation-dialog" class="navigation-dialog" aria-labelledby="navigation-title"><div class="menu-head"><h2 id="navigation-title">Explore Maeve Arden</h2><button class="icon-button" type="button" data-menu-close aria-label="Close navigation"><svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><path d="m3 3 12 12M15 3 3 15" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></button></div><nav aria-label="Mobile navigation">{nav(prefix, active)}<a href="{prefix}contact.html">Check your date {arrow()}</a></nav><p class="eyebrow">Lake District · UK · Europe</p></dialog>'''

def footer(prefix):
    return f'''<footer class="site-footer"><div class="container"><div class="footer-top">{brand(prefix)}<p>A quiet eye. An honest story.<br>Editorial wedding photography, UK & Europe.</p><nav aria-label="Footer navigation"><a href="{prefix}portfolio.html">Selected work</a><a href="{prefix}weddings.html">Collections</a><a href="{prefix}contact.html">Enquire {arrow()}</a></nav></div><div class="footer-bottom"><p>© <span data-year>2026</span> Maeve Arden</p><p>A fictional brand & website concept by <a href="https://github.com/lukebrennan">Luke Brennan</a>.</p><div><a href="{prefix}credits.html">Image credits</a><a href="{prefix}privacy.html">Privacy</a></div></div></div></footer>'''

def lightbox(prefix):
    return f'''<dialog class="lightbox" data-lightbox-dialog aria-labelledby="lightbox-title"><div class="lightbox-top"><div><p class="eyebrow">Selected photographs</p><h2 id="lightbox-title">Photograph</h2></div><button class="icon-button" type="button" data-lightbox-close aria-label="Close photograph"><svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><path d="m3 3 12 12M15 3 3 15" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></button></div><div class="lightbox-image"><img data-lightbox-image src="{prefix}assets/images/hero-480.webp" alt="" loading="lazy" width="1600" height="2000"></div><div class="lightbox-bottom"><a data-lightbox-credit href="{prefix}credits.html"><span data-lightbox-credit-label>Image credit</span>{arrow()}</a><div class="lightbox-controls"><button class="icon-button" type="button" data-lightbox-prev aria-label="Previous photograph"><svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true"><path d="M17 10H3m6-6-6 6 6 6" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></button><span data-lightbox-count aria-live="polite"></span><button class="icon-button" type="button" data-lightbox-next aria-label="Next photograph"><svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true"><path d="M3 10h14m-6-6 6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></button></div></div></dialog>'''

def cta(prefix='', label='Tell me about your plans.'):
    return f'''<section class="closing-cta"><div class="container"><div><p class="eyebrow">Something worth remembering</p><h2>{label}</h2><p>A place, a date, a little about the two of you.</p></div><a class="button button-light" href="{prefix}contact.html">Check your date {arrow()}</a></div></section>'''

PAGES = []
def page(path, title, desc, body, active='', image='hero', kind='WebPage', crumbs=None, lightbox_needed=False):
    prefix = '../' * path.count('/')
    url = BASE + ('' if path == 'index.html' else path)
    title = title + ' | Maeve Arden Photography'
    graph = [{ '@type':'WebSite', '@id': BASE+'#website', 'url':BASE, 'name':'Maeve Arden Photography', 'description':'An editorial wedding photography website concept by Luke Brennan.' },
             {'@type':kind, '@id':url+'#page', 'name':title, 'description':desc, 'url':url, 'isPartOf':{'@id':BASE+'#website'}}]
    if crumbs:
        graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':name,'item':BASE+slug} for i,(name,slug) in enumerate([('Home','')]+crumbs)]})
    if kind == 'Article':
        graph[1].update({'headline':title.split(' | ')[0], 'image':BASE+'assets/images/social.jpg', 'author':{'@type':'Person','name':'Luke Brennan','url':'https://github.com/lukebrennan'}})
    robots = 'noindex,follow' if path == '404.html' else 'index,follow,max-image-preview:large'
    preload = f'<link rel="preload" as="image" type="image/avif" href="{prefix}assets/images/embrace-800.avif" imagesrcset="{prefix}assets/images/embrace-480.avif 480w, {prefix}assets/images/embrace-800.avif 800w, {prefix}assets/images/embrace-1200.avif 1200w, {prefix}assets/images/embrace-1600.avif 1600w" imagesizes="(max-width: 600px) calc(100vw - 40px), (max-width: 900px) 68vw, 53vw" fetchpriority="high">' if path=='index.html' else ''
    html = f'''<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc, quote=True)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#f7f5ef"><link rel="canonical" href="{url}"><meta property="og:type" content="{'article' if kind=='Article' else 'website'}"><meta property="og:title" content="{escape(title, quote=True)}"><meta property="og:description" content="{escape(desc, quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/images/social.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Bride and groom laughing together — Maeve Arden Photography concept"><meta property="og:locale" content="en_GB"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="{prefix}assets/icons/favicon.svg?v={FAVICON_VERSION}"><link rel="manifest" href="{prefix}site.webmanifest">{preload}<link rel="preload" as="font" type="font/woff2" crossorigin href="{prefix}assets/fonts/geologica-latin.woff2"><link rel="preload" as="font" type="font/woff2" crossorigin href="{prefix}assets/fonts/bodoni-moda-latin.woff2"><link rel="stylesheet" href="{prefix}assets/css/style.css?v={CSS_VERSION}"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph}, ensure_ascii=False)}</script><script src="{prefix}assets/js/main.js?v={JS_VERSION}" defer></script></head><body data-asset-prefix="{prefix}">{header(prefix,active)}<main id="main" tabindex="-1">{body}</main>{footer(prefix)}{lightbox(prefix) if lightbox_needed else ''}{'<a class="mobile-enquire" href="'+prefix+'contact.html">Check your date '+arrow()+'</a>' if active!='contact' else ''}</body></html>'''
    if path == '404.html':
        # GitHub serves 404.html at arbitrary nested URLs. Keep the error page
        # self-contained and point recovery links at the real project root.
        html = html.replace(f'<link rel="stylesheet" href="{prefix}assets/css/style.css?v={CSS_VERSION}">', '<style>'+css.replace('../fonts/',BASE+'assets/fonts/')+'</style>')
        html = re.sub(r'<script src="[^"]+" defer></script>', '', html)
        # Keep recovery branding sharp and self-contained at arbitrary URLs.
        error_logo = (ROOT/'assets/icons/maeve-arden-wordmark.svg').read_text()
        error_logo = re.sub(r'<title[^>]*>.*?</title>', '', error_logo, flags=re.S)
        error_logo = re.sub(r' aria-labelledby="[^"]+"', '', error_logo)
        error_logo = error_logo.replace('<svg ', '<svg class="brand-logo" aria-hidden="true" ')
        error_logo = '\n'.join(line.rstrip() for line in error_logo.splitlines()).strip()
        error_brand = f'<a class="brand" href="{BASE}" aria-label="Maeve Arden Photography home">{error_logo}</a>'
        html = re.sub(r'<header class="site-header">.*?</header>', f'<header class="site-header"><div class="header-inner">{error_brand}<a class="text-link" href="{BASE}">Home</a></div></header>', html)
        html = re.sub(r'<dialog id="navigation-dialog".*?</dialog>', '', html)
        html = re.sub(r'<footer class="site-footer">.*?</footer>', '<footer class="site-footer"><div class="container footer-bottom"><p>A fictional brand & website concept by Luke Brennan.</p><a href="'+BASE+'credits.html">Image credits</a></div></footer>', html)
        html = re.sub(r'<a class="mobile-enquire".*?</a>', '', html)
        html = re.sub(r'href="(?!https?:|#)([^"]+)"', lambda match:'href="'+BASE+match.group(1)+'"', html)
    html = re.sub(r'<p class="eyebrow">.*?</p>', '', html)
    html = re.sub(r'<span class="eyebrow">.*?</span>', '', html)
    target = ROOT/path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(html, encoding='utf-8')
    if path != '404.html':
        PAGES.append(url)

def intro(eyebrow, heading, desc='', prefix='', crumb=None):
    breadcrumb = f'<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="{prefix}index.html">Home</a><span aria-hidden="true">/</span><span>{crumb}</span></nav>' if crumb else ''
    return f'<section class="page-intro container">{breadcrumb}<h1>{heading}</h1>'+ (f'<p class="intro-summary">{desc}</p>' if desc else '') + '</section>'

def workcard(key, name, subtitle, number, href, cls=''):
    return f'<a class="work-card {cls}" href="{href}"><div class="work-image">{picture(key,sizes="(max-width: 760px) calc(100vw - 40px), 32vw")}<span class="image-action">Explore story {arrow()}</span></div><div class="work-caption"><div><span class="eyebrow">{subtitle}</span><h3>{name}</h3></div><span class="work-number">{number} {arrow()}</span></div></a>'

def journalcard(key, category, title, href, length, heading='h3'):
    return f'<a class="journal-card" href="{href}"><div class="journal-image">{picture(key,sizes="(max-width: 760px) calc(100vw - 40px), 32vw")}</div><div class="journal-meta"><span class="eyebrow">{category} · {length} min read</span><{heading}>{title}</{heading}><span class="text-link">Read the notes {arrow()}</span></div></a>'

