rail = ''.join(f'<a class="photo-print" href="assets/images/{key}-1600.webp" data-lightbox="{key}" data-title="{title}" aria-label="View photograph: {title}"><div class="print-image">{picture(key,sizes="(max-width: 600px) 72vw, 28vw")}<span class="print-open">View photograph {expand_icon()}</span></div><span class="print-caption">{title}</span></a>' for key,title in rail_photos)
home = f'''<section class="folio container" aria-labelledby="folio-title"><div class="folio-intro"><h1 id="folio-title">Wedding photography,<br>with room to be you.</h1><p>A considered eye. A day that feels like yours.<br>From the Lake District to wherever you go.</p></div><div class="folio-stage" data-folio><div class="folio-images" id="folio-images"><figure class="folio-main"><a class="folio-photo" href="stories/after-the-quiet.html" data-folio-primary data-photo="embrace" aria-label="Explore All the feeling">{picture('embrace',sizes='(max-width: 600px) calc(100vw - 40px), (max-width: 900px) 68vw, 53vw',eager=True)}</a><figcaption class="folio-caption"><span data-folio-caption><strong>All the feeling</strong>Candid moments · A visual study</span><a href="stories/after-the-quiet.html" data-folio-story>View story {arrow()}</a></figcaption><div class="folio-paging" data-folio-controls hidden><button class="icon-button" type="button" data-scene-prev aria-label="Previous selection">{previous_arrow()}</button><span data-scene-count>1 / 3</span><button class="icon-button" type="button" data-scene-next aria-label="Next selection">{arrow()}</button><span class="folio-feedback" role="status" data-folio-status></span></div><p class="mobile-collection"><a href="weddings.html#collections">Full-day collections from £2,850</a></p></figure><figure class="folio-secondary"><a class="folio-photo" href="portfolio.html#hero" data-folio-secondary aria-label="View laughing wedding portrait">{picture('hero',sizes='(max-width: 600px) 0px, 21vw')}</a><figcaption>For the moments<br>that feel like you.</figcaption></figure></div><aside class="folio-index"><div data-folio-controls hidden><h2>Choose a preview</h2><div class="scene-previews" aria-label="Photographic previews" role="group">{previews}</div></div><noscript><p><a href="stories/after-the-quiet.html">Candid moments</a> · <a href="stories/still-water.html">People & place</a> · <a href="stories/city-softened.html">Quiet portraits</a></p></noscript><div class="folio-practical"><p>Based in the Lake District.<br>Photographing across the UK & Europe.</p><p>Full-day collections<strong>From £2,850</strong></p><a class="text-link" href="contact.html">Check your date {arrow()}</a><br><a class="text-link" href="portfolio.html">All photographs {arrow()}</a></div></aside></div></section>
<section class="container approach-note"><h2>Good photographs should<br>take you back to how it felt.</h2><div><p>The people you love. The place you chose. The unplanned moments in between. A little guidance when you need it, and room to enjoy the rest.</p><a class="text-link" href="about.html">Meet the approach {arrow()}</a></div></section>
<section class="home-photographs container" aria-labelledby="photographs-title"><div class="section-heading"><h2 id="photographs-title">A little more of the day.</h2><a class="text-link" href="portfolio.html">View the full portfolio {arrow()}</a></div><div class="print-toolbar"><p>Open a photograph. Stay a little longer.</p><div class="rail-controls" data-rail-controls hidden><button class="icon-button" type="button" data-rail-prev aria-label="Previous photographs" aria-controls="home-photographs">{previous_arrow()}</button><button class="icon-button" type="button" data-rail-next aria-label="Next photographs" aria-controls="home-photographs">{arrow()}</button></div></div><div class="photo-rail" id="home-photographs" tabindex="0" role="region" aria-label="More wedding photographs, scroll horizontally">{rail}</div><p class="small-note">A photographic mood, drawn from credited stock images for this fictional brand. <a href="credits.html">Image credits</a></p></section>
<section class="experience-section" aria-labelledby="experience-title"><div class="container experience-grid"><div class="experience-image">{picture('flowers',sizes='(max-width: 600px) 45vw, 38vw')}<span class="image-caption">The setting matters.<br>The people make it yours.</span></div><div class="experience-copy"><h2 id="experience-title">More time in the moment.</h2><p>You deserve to enjoy your wedding. We plan the important photographs and leave space for the day to unfold.</p><div class="experience-point"><h3>Before the day</h3><p>A conversation about your plans, your people and what you hope to remember.</p></div><div class="experience-point"><h3>On the day</h3><p>Calm direction for portraits. An unobtrusive presence for everything else.</p></div><div class="experience-point"><h3>For the years ahead</h3><p>A complete gallery to revisit, print and share.</p></div><a class="text-link" href="weddings.html#collections">Explore the collections · from £1,450 {arrow()}</a></div></div></section>
<section class="section container" aria-labelledby="journal-title"><div class="section-heading"><h2 id="journal-title">A few things worth knowing.</h2><a class="text-link" href="journal.html">From the journal {arrow()}</a></div><div class="journal-feature"><a class="journal-feature-image" href="journal/lake-district-wedding-photography.html" aria-label="Read Making room for the Lake District">{picture('lake-sunset',sizes='(max-width: 600px) calc(100vw - 40px), 50vw')}</a><div class="journal-links"><a href="journal/lake-district-wedding-photography.html"><h3>Making room for the Lake District</h3><span>Places · 3 min read</span></a><a href="journal/editorial-wedding-photographs.html"><h3>Editorial photographs, naturally</h3><span>Planning · 2 min read</span></a><a href="journal/london-wedding-portraits.html"><h3>Finding a quiet moment in London</h3><span>City weddings · 2 min read</span></a></div></div></section>{cta()}'''
