portfolio = intro('A considered collection','Selected photographs.','People, place and the little things that make a day its own. Open a photograph to see it in full, or explore a visual story below.',crumb='Selected work') + f'''<section class="container gallery-section" aria-label="Photography portfolio"><div class="gallery-toolbar" data-gallery-toolbar hidden><div class="gallery-filters" role="group" aria-label="Filter photographs">{''.join(f'<button type="button" data-filter="{value}" aria-pressed="{str(value=="all").lower()}">{label}</button>' for value,label in [('all','All work'),('celebrations','Celebrations'),('portraits','Portraits'),('places','Places'),('details','Details')])}</div><p data-gallery-status role="status">14 photographs</p></div><div class="gallery-grid">{tiles}</div><p class="small-note">A curated collection of stock photography for this website concept. <a href="credits.html">Meet the photographers {arrow()}</a></p></section><section class="section container"><div class="section-heading"><h2>Three visual stories.</h2></div><div class="work-grid">{workcard('meadow','Room to Breathe','People & place','01','stories/still-water.html')}{workcard('editorial','City, Softened','Quiet portraits','02','stories/city-softened.html')}{workcard('embrace','After the Quiet','Celebrations','03','stories/after-the-quiet.html')}</div></section>{cta()}'''
