for value,name,price,desc,features in collections:
    prices+=f'<article class="price-card {"featured" if value=="story" else ""}" id="{value}"><p class="eyebrow">{"The full-day collection" if value=="story" else "Intimate celebrations" if value=="intimate" else "Weekend celebrations"}</p><h3>{name}</h3><p>{desc}</p><div class="price"><span>From</span> {price}</div><ul>{"".join("<li>"+f+"</li>" for f in features)}</ul><a class="button {"button-light" if value=="story" else "button-outline"}" href="contact.html?collection={value}">Enquire about this collection {arrow()}</a></article>'
faqs=[('What if we feel awkward in front of the camera?','You are in good company. Simple prompts, movement and good light give you something to do without asking you to perform. Portrait time can be short and relaxed.'),('Can we choose a destination wedding?','Yes. For the concept, destination coverage is tailored around the celebration, with travel shown separately in a personal quote. Choose “Destination” on the enquiry form to explore that journey.'),('How much time should we set aside for portraits?','A short, flexible window is a useful starting point. Discuss the light, locations and any family groups in advance so photographs fit comfortably around the day.'),('Can we customise a collection?','The collections are starting points. Additional coverage, albums and a second photographer can be discussed around the plans. The enquiry form lets you share what you have in mind.'),('Is this a real photography business?','Maeve Arden is a fictional brand created as a web design and development portfolio project. Images are credited stock photography, prices illustrate the service journey, and the form previews an enquiry without sending it.')]
weddings = intro('The experience & collections','The experience & collections.','Editorial in feel, documentary at heart. Thoughtful coverage that makes room for your people, your plans and everything in between.',crumb='The experience')+f'''<div class="container wide-photo">{picture('embrace',sizes='(max-width: 760px) calc(100vw - 40px), 90vw',eager=True)}</div><section class="section container" id="collections" aria-labelledby="collections-title"><div class="section-heading"><div><p class="eyebrow">Your day, your collection</p><h2 id="collections-title">Simple, considered coverage.</h2></div><p>Planning support, thoughtful editing and a private gallery come with every collection.</p></div><div class="pricing-grid">{prices}</div><p class="small-note">Illustrative collections for this portfolio concept. Destination travel and any additions would be confirmed in a personal quote.</p></section><section class="experience-section" id="destinations"><div class="container split-story"><div>{picture('lake-sunset',sizes='(max-width: 760px) calc(100vw - 40px), 47vw')}</div><div><p class="eyebrow">Somewhere a little further</p><h2>A familiar presence.<br><em>An unforgettable place.</em></h2><p>For weddings in Italy and across Europe, make space for the whole celebration. A welcome evening, the wedding day, perhaps a quiet morning after.</p><a class="text-link" href="contact.html?collection=destination">Talk about a destination wedding {arrow()}</a></div></div></section><section class="section container faq-section" aria-labelledby="faq-title"><div><p class="eyebrow">A few things you might wonder</p><h2 id="faq-title">Before you enquire.</h2><p>More about the approach and what happens next.</p></div><div class="faq-list">{''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in faqs)}</div></section>{cta()}'''
page('weddings.html','Wedding Collections & Experience','Explore relaxed wedding photography collections, intimate celebrations and destination coverage in the Maeve Arden website concept. Full-day collections from £2,850.',weddings,active='weddings',crumbs=[('The experience','weddings.html')],image='celebration')

about = intro('A quiet eye for an honest story','A little about the approach.','The best photographs take you back to how it felt. The wind, the laughter, the people. All of it.',crumb='About')+f'''<section class="container about-layout"><div class="about-image">{picture('evening',sizes='(max-width: 760px) calc(100vw - 40px), 47vw',eager=True)}<span class="image-caption">A little space to let the day be yours.</span></div><div class="about-copy"><p class="eyebrow">Meet the approach</p><h2>Part observer.<br>Part director.<br><em>Always present.</em></h2><p>Maeve Arden’s world is quietly editorial: considered composition, beautiful light and photographs that still feel like you.</p><p>The approach brings people and place together. Help when direction is useful, space when it isn’t, and attention to the gestures and glances that make a story personal.</p><p>From a lakeside celebration to a city wedding, the idea is the same: plan carefully, guide lightly, and leave room for life.</p><a class="text-link" href="weddings.html">Discover the experience {arrow()}</a></div></section><section class="section container"><div class="values-grid"><article><p class="eyebrow">01 / Elegant</p><h2>A considered eye.</h2><p>Beautiful light and intentional composition, with an editorial finish that feels natural.</p></article><article><p class="eyebrow">02 / Honest</p><h2>A personal story.</h2><p>Real expressions and movement. The photographs that feel like you, long after trends pass.</p></article><article><p class="eyebrow">03 / Alive</p><h2>Room for the unexpected.</h2><p>The laughter after a portrait. A veil caught in the wind. A hand squeezed under the table.</p></article></div></section><section class="concept-note container"><p class="eyebrow">Behind the concept</p><h2>Made with care, by Luke Brennan.</h2><p>Maeve Arden is a fictional photography brand created to explore thoughtful web design: an image-led identity, an accessible gallery, a clear enquiry journey and a fast, lightweight website. Every photograph is credited to its original creator.</p><a class="text-link" href="credits.html">Meet the photographers {arrow()}</a></section>{cta()}'''
page('about.html','About the Editorial Photography Approach','Discover the quiet editorial approach behind Maeve Arden, a fictional photography brand and carefully crafted website portfolio concept by Luke Brennan.',about,active='about',crumbs=[('About','about.html')],image='evening')

journal = intro('Field notes','From the journal.','Useful thoughts on light, place and making room for photographs without losing the day.',crumb='Journal')+f'''<section class="container journal-list" aria-label="Journal articles"><div class="journal-grid">{journalcard('still-water','Places','Making room for the Lake District','journal/lake-district-wedding-photography.html',3,heading='h2')}{journalcard('table','Planning','Editorial photographs, naturally','journal/editorial-wedding-photographs.html',2,heading='h2')}{journalcard('city-softened','City weddings','Finding a quiet moment in London','journal/london-wedding-portraits.html',2,heading='h2')}</div></section>{cta()}'''
page('journal.html','Wedding Planning Notes & Inspiration','Wedding photography planning notes from the Maeve Arden concept: the Lake District, natural editorial photographs and relaxed London wedding portraits.',journal,active='journal',kind='CollectionPage',crumbs=[('Journal','journal.html')])

articles = [
('lake-district-wedding-photography','Making room for the Lake District','Places','still-water',3,'Water, woodland, stone and changing light. Make the landscape part of the day without making it the whole day.',[
('Let the weather into the story','Low cloud, a breeze and a little rain can give photographs texture and atmosphere. Build a practical fallback into your plans: a sheltered spot, somewhere with good window light, and shoes that can cope with the ground. The aim is flexibility, so a change in weather doesn’t take over the day.'),
('Keep an evening window flexible','A short break for portraits can be enough. Rather than disappearing for an hour, leave a little room in the schedule to step outside when the light works. Talk through that possibility beforehand, and keep dinner, speeches and your guests at the centre of the plan.'),
('Think beyond the big view','The setting can appear quietly: reflections, wet foliage, old stone, a line of trees. Mixing wider views with close portraits and small details creates a varied story. You don’t need to chase every landmark to make the photographs feel rooted in a place.'),
('Look for variety close to the venue','When choosing a venue, think about covered areas, accessible paths and indoor light as well as the ceremony space. Nearby options make it easier to adapt without spending your wedding day travelling between locations. Ask your venue about access and permissions before planning a lakeside route.'),
('Keep the day yours','The photographs should fit around the celebration. Plan the important group pictures, share any access needs, and leave space for the spontaneous moments. The landscape is a wonderful backdrop, but the people are the story.')]),
('editorial-wedding-photographs','Editorial photographs, naturally','Planning','table',2,'A considered photograph can still feel spontaneous. A few thoughtful choices make that balance easier.',[
('Give good light a little room','For preparations, a calm spot near a window often gives you more options than a crowded corner under ceiling lights. Clear a little space beforehand, then let the morning happen. You don’t need to stage the entire room.'),
('Choose movement over performance','Walking together, talking and taking a moment to breathe give portraits life. Simple direction can help you feel comfortable without prescribing every expression. Share what feels natural to you and what you would rather avoid.'),
('Plan the essentials, then let go','Write down the family groups you care about and agree a realistic time for them. Keep the list focused. Once those essentials are covered, there is more space for photographs of the conversations, gestures and energy that can’t be planned.'),
('Let the details belong to the day','A beautiful table matters because people will gather around it. Photograph the design and the atmosphere around it: hands reaching for glasses, flowers in changing light, a room beginning to fill. The details become richer when they connect to the people.'),
('Talk about what matters','Tell your photographer what you hope to remember, not just which photographs you have seen online. A person, a feeling, a tradition or a quiet moment can be a more useful starting point than a long list of poses.')]),
('london-wedding-portraits','Finding a quiet moment in London','City weddings','city-softened',2,'City texture, a little movement and somewhere to pause. Portraits can be part of the journey, rather than a long detour.',[
('Keep the route short','Choose one or two portrait locations near your venue, then plan a simple route. Long journeys can quickly eat into a wedding schedule. A doorway, a stretch of pavement or a sheltered courtyard may be all you need.'),
('Look for calm within the city','Interesting light and texture are often more useful than a recognisable landmark. Look for open shade, pale stone, reflections and quiet corners. A place you can enjoy for a few minutes is more valuable than a busy backdrop you have to fight.'),
('Check access before the day','A public-looking space may still have photography restrictions. Confirm access with the venue or landowner, especially for indoor locations or a larger setup. Keep a nearby alternative so one unavailable spot doesn’t upset the plan.'),
('Make room for the unexpected','Traffic, crowds and weather can change the feel of a route. Build in a little breathing room and keep the plan adaptable. If a location is crowded, use a closer frame, move to a quieter corner, or return to the venue.'),
('Stay connected to the celebration','Portraits can be a brief pause together before you return to your guests. Agree a comfortable amount of time in advance. The city gives you the setting; your connection gives the photographs their meaning.')])]
for slug,title,category,key,length,lede,sections in articles:
    content = f'''<section class="article-heading container"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="../index.html">Home</a><span aria-hidden="true">/</span><a href="../journal.html">Journal</a></nav><p class="eyebrow">{category} · {length} min read</p><h1>{title}</h1><p class="intro-summary">{lede}</p></section><figure class="container article-cover">{picture(key,prefix='../',sizes='(max-width: 760px) calc(100vw - 40px), 90vw',eager=True)}<figcaption>Photograph by {PHOTOS[key][1]}. <a href="../credits.html">Image credits</a></figcaption></figure><div class="container article-layout"><aside class="article-toc"><p class="eyebrow">In these notes</p><nav aria-label="Article sections">{''.join(f'<a href="#note-{i}">{heading}</a>' for i,(heading,text) in enumerate(sections))}</nav></aside><article class="article-body">{''.join(f'<section id="note-{i}"><h2>{heading}</h2><p>{text}</p></section>' for i,(heading,text) in enumerate(sections))}<div class="article-next"><p class="eyebrow">The next step</p><h2>Make room for your story.</h2><p>Explore the collections or share a little about your plans.</p><a class="text-link" href="../weddings.html">Explore the experience {arrow()}</a></div></article></div><section class="section container"><div class="section-heading"><div><p class="eyebrow">Continue exploring</p><h2>More from the field notes.</h2></div><a class="text-link" href="../journal.html">All notes {arrow()}</a></div><div class="journal-grid">{''.join(journalcard(other[3],other[2],other[1],other[0]+'.html',other[4]).replace('assets/images/','../assets/images/') for other in articles if other[0]!=slug)}</div></section>{cta('../')}'''
    page('journal/'+slug+'.html',title,lede,content,active='journal',image=key,kind='Article',crumbs=[('Journal','journal.html'),(title,'journal/'+slug+'.html')])

stories=[('still-water','Room to Breathe','People & place','meadow',['meadow','hands','lake-sunset','flowers','vows'],'Open spaces, soft light and a little room to breathe. A photographic study in people and place.'),('city-softened','City, Softened','Quiet portraits','editorial',['editorial','bridal','bouquet','hero','table'],'A quiet moment in a busy world. A photographic study in connection, texture and natural portraits.'),('after-the-quiet','After the Quiet','Candid moments','embrace',['embrace','celebration','dance','sparklers','hero'],'The confetti, the laughter, the room coming alive. A photographic study in the energy of a celebration.')]

for index,(slug,title,subtitle,key,keys,desc) in enumerate(stories):
    images=''
    for i,photo in enumerate(keys):
        images += f'<a href="../assets/images/{photo}-1600.webp" data-lightbox="{photo}" data-title="{title} · {i+1:02d}" class="story-photograph" aria-label="View photograph {i+1}: {PHOTOS[photo][0]}">{picture(photo,prefix="../",sizes="(max-width: 760px) calc(100vw - 40px), 80vw",eager=i==0)}<span class="gallery-expand" aria-hidden="true"><svg width="18" height="18" viewBox="0 0 18 18"><path d="M4 14 14 4M4 4h10v10" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></span></a>'
    nxt=stories[(index+1)%len(stories)]
    content=intro(subtitle,title,desc,prefix='../',crumb='Selected story')+f'''<section class="container story-gallery" aria-label="{title} photographs">{images}</section><div class="container story-note"><span class="eyebrow">A visual study</span><p>This gallery combines credited stock photographs to demonstrate the website’s story experience. It represents a visual direction, rather than a client wedding. <a href="../credits.html">View image credits.</a></p></div><section class="next-story container"><p class="eyebrow">Next story</p><a href="{nxt[0]}.html"><h2>Next story: {nxt[1]}</h2>{arrow()}</a><a class="text-link" href="../portfolio.html">Back to all work {arrow()}</a></section>{cta('../')}'''
    page('stories/'+slug+'.html',title+' — Wedding Photography Study',desc,content,active='portfolio',image=key,crumbs=[('Selected work','portfolio.html'),(title,'stories/'+slug+'.html')],lightbox_needed=True)

contact=intro('Your story starts here','Tell me about your day.','Tell me what you’re planning. A few details are all it takes to start the conversation.',crumb='Enquire')+f'''<section class="container enquiry-layout" aria-labelledby="enquiry-heading"><aside class="enquiry-aside"><div class="enquiry-photo">{picture('hero',sizes='(max-width: 760px) 0px, 30vw')}</div><div class="enquiry-reassurance"><h2 id="enquiry-heading">A simple first step.</h2><p>Choose a collection, share your plans and preview your enquiry. No obligation, no long questionnaire.</p><a class="text-link" href="weddings.html#collections">Compare the collections {arrow()}</a></div></aside><div class="enquiry-panel"><div class="demo-notice"><span class="status-dot" aria-hidden="true"></span><p><strong>Portfolio demo.</strong> This form creates a preview. Your details aren’t sent or saved.</p></div><noscript><p class="demo-notice">JavaScript is needed to try the enquiry preview. Explore the collections and photography using the links above.</p></noscript><form data-enquiry-form novalidate><fieldset disabled data-form-fields><legend class="visually-hidden">Enquiry details</legend><ol class="form-progress" aria-label="Enquiry steps"><li class="current" data-step-indicator="1" aria-current="step"><span>01</span> Your plans</li><li data-step-indicator="2"><span>02</span> About you</li></ol><div class="form-error-summary" role="alert" data-error-summary hidden></div><section data-form-step="1" aria-labelledby="plans-title"><h2 id="plans-title" tabindex="-1">What are you planning?</h2><fieldset class="collection-options"><legend>Your collection</legend>{''.join(f'<label><input type="radio" name="collection" value="{v}" {"checked" if v=="story" else ""}><span><strong>{name}</strong><small>{price}</small></span></label>' for v,name,price in [('intimate','The Intimate','From £1,450'),('story','The Story','From £2,850'),('complete','The Complete','From £4,900'),('destination','Destination','Bespoke')])}</fieldset><div class="form-grid"><div class="field"><label for="date">Wedding date <span data-date-required>(required)</span></label><input type="date" id="date" name="date" aria-describedby="date-error" required><span id="date-error" class="field-error"></span><label class="checkbox-label"><input type="checkbox" name="flexible" id="flexible"> We haven’t set a date yet</label></div><div class="field"><label for="venue">Venue or location <span>(optional)</span></label><input type="text" id="venue" name="venue" maxlength="160" placeholder="A venue, a town, a country…" autocomplete="off"></div></div><div class="form-actions"><span>About a minute, altogether.</span><button type="button" class="button" data-next-step>Continue {arrow()}</button></div></section><section data-form-step="2" aria-labelledby="about-you-title" hidden><h2 id="about-you-title" tabindex="-1">And a little about you.</h2><div class="form-grid"><div class="field"><label for="name">Your name(s) <span>(required)</span></label><input id="name" name="name" autocomplete="name" maxlength="120" required aria-describedby="name-error" placeholder="e.g. Alex & Sam"><span id="name-error" class="field-error"></span></div><div class="field"><label for="email">Email address <span>(required)</span></label><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required aria-describedby="email-error" placeholder="you@example.com"><span id="email-error" class="field-error"></span></div><div class="field full"><label for="message">Tell me about the day <span>(optional)</span></label><textarea id="message" name="message" rows="4" maxlength="2000" placeholder="What matters most? What do you want to remember?"></textarea></div></div><div class="enquiry-summary" data-enquiry-summary></div><div class="form-actions"><button type="button" class="text-link" data-previous-step>← Back to your plans</button><button type="submit" class="button">Preview enquiry {arrow()}</button></div><p class="form-note">Nothing is sent or stored. <a href="privacy.html">How this demo uses your details.</a></p></section></fieldset></form><section class="enquiry-result" data-enquiry-result hidden aria-labelledby="result-title"><p class="eyebrow">Your story, at a glance</p><h2 id="result-title" tabindex="-1">Your enquiry preview<br><em>is ready.</em></h2><p>This is how your enquiry would look. This portfolio demo hasn’t sent your details, checked availability or reserved a date.</p><dl data-result-details></dl><div class="form-actions"><button type="button" class="text-link" data-edit-enquiry>← Edit your details</button><button type="button" class="button" data-copy-enquiry>Copy enquiry {arrow()}</button></div><p role="status" data-copy-status></p></section></div></section>'''
page('contact.html','Check Your Wedding Date','Try the Maeve Arden enquiry journey: choose a collection, share your date and preview your wedding photography enquiry. Portfolio demonstration; details are not sent.',contact,active='contact',crumbs=[('Enquire','contact.html')],image='hero')

credits=intro('With thanks to the photographers','The photographers.','The imagery in this fictional portfolio belongs to the photographers credited below. Their work brings the concept to life.',crumb='Image credits')+'<section class="container credits-list" aria-label="Photographer credits">'+''.join(f'<article class="credit-row">{picture(key,sizes="120px")}<div><h2>{photographer}</h2><p>{alt}</p><a class="text-link" href="https://unsplash.com/photos/{photo_id}">Original photograph on Unsplash {arrow()}</a></div></article>' for key,(alt,photographer,photo_id) in PHOTOS.items())+'</section><section class="container prose-panel"><h2>Photography & the concept</h2><p>Maeve Arden is a fictional brand. These images demonstrate the design and gallery experience; they are not photographs made by Maeve Arden or Luke Brennan.</p><p>Images were downloaded and optimised locally as responsive AVIF and WebP files. The <a href="https://unsplash.com/license">Unsplash License</a> permits free commercial and non-commercial use. Full source records are included in the repository’s IMAGE-SOURCES.md.</p></section>'
page('credits.html','Image Credits', 'Photographer credits, source links and image licensing for the stock photographs used in the fictional Maeve Arden website concept.', credits,crumbs=[('Image credits','credits.html')])
privacy=intro('Simple and transparent','Privacy & the enquiry demo.',crumb='Privacy')+'''<article class="container prose-panel"><h2>A portfolio demonstration</h2><p>Maeve Arden is a fictional photography brand and this site is a design and development portfolio project by Luke Brennan.</p><h2>The enquiry preview</h2><p>The form uses your details in your browser to display an enquiry preview. It does not send them to a server, check a real calendar or store them in cookies or browser storage. The preview exists only in the current page; this website does not save your form details for later visits.</p><p>If you choose “Copy enquiry”, the text is copied to your device’s clipboard. You control what you do with that copy.</p><h2>Images, cookies and analytics</h2><p>Photographs are served from the same website. This site does not add analytics, advertising, cookies or tracking scripts. The hosting provider may process ordinary connection information, such as IP addresses, to serve and protect the website.</p><h2>External links</h2><p>Links to GitHub and Unsplash take you to services with their own privacy policies. You can review those policies on the respective services.</p></article>'''
page('privacy.html','Privacy & Enquiry Demo','How the Maeve Arden portfolio demonstration handles enquiry details: browser-only previews, no form transmission, no analytics and local photography.',privacy,crumbs=[('Privacy','privacy.html')])
page('404.html','Page Not Found','This page could not be found. Return to the Maeve Arden photography portfolio or explore the collections.',intro('A small detour','That page isn’t here.','Let’s get you back to the photographs.')+'<div class="container error-page-actions"><a class="button" href="index.html">Back to home ↗</a><a class="text-link" href="portfolio.html">Explore the work ↗</a></div>')

